import SwiftUI

enum PrivacyPolicy {
    static let url = URL(string: "https://alonsojrr14.github.io/gymbros/privacidade/")!
    static let updated = "21 de outubro de 2026"

    static let sections: [(title: String, text: String)] = [
        ("Resumo", "O GymBros não tem anúncios, não rastreia você e não usa ferramentas de análise. Para usar o app é preciso uma conta: treinos, bros e o resto do progresso pertencem a ela, não ao aparelho. A conta e o que você publica ficam no Firebase, serviço do Google que o GymBros usa como servidor (login e banco de dados, no Brasil, na região de São Paulo). Só quem precisa vê cada dado: o que é seu só você; o que você publica, só as pessoas indicadas abaixo."),
        ("Dados da sua conta", "Atividades, treinos, séries, recordes, rotinas, medidas, fotos, academias salvas, rotas de corrida, ligas, recados, o seu perfil e os seus ajustes são da sua conta. O iPhone guarda a cópia que você usa, protegida pela criptografia do aparelho, e uma cópia completa num arquivo dentro do app. Depois de cada mudança, uma cópia vai para o servidor, comprimida e acessível só pela sua conta; nela não vão as fotos de medidas, de check-ins e do mural (ficam só no iPhone), mas vão a foto do perfil e as capas das ligas. Ao sair da conta, os dados saem do iPhone e voltam quando você entra de novo; num iPhone novo, voltam sem as fotos que não foram para o servidor. Quem entrar com outra conta no mesmo iPhone não vê nada da sua. O widget lê um resumo (nome e forma do bro, XP, sequência e rotina do dia) por um espaço compartilhado só entre o app e o widget, apagado ao sair."),
        ("Apple Saúde", "Se você permitir, o app lê os seus treinos do Apple Saúde (tipo, duração, calorias e distância) para transformá-los em atividades e, se você ligar a gravação, grava no Saúde as atividades registradas aqui. Esses dados não são usados para publicidade nem compartilhados com terceiros. O que vem do Saúde entra nos dados da sua conta e, com eles, na cópia guardada no servidor do GymBros (Firebase), nunca no iCloud. Calorias, distância e esforço vindos do Saúde nunca vão para posts nem para o X1. Se você postar uma atividade importada do Saúde no perfil ou numa liga, o post leva o tipo, a data e a duração do treino, visíveis para quem vê o post. Dá para desligar a qualquer momento em Ajustes do iPhone > Saúde > Acesso a Dados."),
        ("Música", "Desligado por padrão. Se você ligar \"Mostrar o que estou ouvindo\" em Ajustes > Música, o app lê só a música que está tocando agora (título, artista e serviço), com a sua permissão, e envia junto com o seu treino ao vivo, para os seus amigos verem enquanto você treina. Nada do seu histórico, das suas playlists ou da sua biblioteca é lido ou enviado. Desligue quando quiser em Ajustes > Música ou tire a permissão em Ajustes do iPhone > GymBros."),
        ("Localização", "Com a sua permissão, o app usa a localização para salvar academias, avisar quando você chega ou sai de uma delas e desenhar a rota de corridas e pedaladas que você grava. Academias e rotas fazem parte dos dados da sua conta. A localização é compartilhada em dois casos. Treino ao vivo: enquanto você está num treino, vão para o servidor e para os amigos que adicionaram você a atividade, o exercício atual e onde você está (numa academia salva, o ponto dela; fora, a sua posição; em corrida, caminhada e bike, também o percurso recente), atualizados no máximo a cada 30 segundos. Ao terminar, fica só o tipo do treino e quando ele acabou. Vem ligado, e o primeiro acesso explica e deixa desligar; depois, dá para escolher em cada treino, no chip \"Ao vivo\", ou mudar o padrão em Mapa > Ajustes (engrenagem). Convite para treinar junto: se você escolher uma academia salva como local do convite, o nome e as coordenadas dela vão para o amigo convidado; digitar o local à mão envia só o texto."),
        ("Fotos", "Fotos só entram no app quando você escolhe uma da galeria ou tira uma na câmera do app (atividade, check-in, perfil ou medidas). A câmera só abre quando você toca em \"Tirar foto\". Da foto da galeria, o app lê só a data e a hora em que ela foi tirada e se ela tem um local gravado, para as ligas que verificam o check-in; as coordenadas não são guardadas nem enviadas. Nesta versão, as fotos de check-in, do mural e de medidas não saem do iPhone; a do perfil vai na cópia da conta. Ao compartilhar um Story ou a retrospectiva, a imagem ou o vídeo vão para o app que você escolher na tela de compartilhar. Se você escolher \"Salvar\", o iPhone pede permissão só para adicionar às suas fotos; o app não lê a sua galeria."),
        ("Ligas, amigos e conta", "Para criar a conta, o app envia ao Firebase o seu nome, e-mail e senha; a senha é guardada pelo Google de forma que nem o GymBros consegue lê-la. Nada é publicado sem você escolher postar. O seu perfil público (nome, usuário, bio, bro, código de amigo e os números e conquistas que você deixar aparecer) pode ser visto por quem tem conta no app. Check-ins, recados e o seu nome e bro numa liga são vistos pelos participantes dela. Mensagens diretas (texto, força e convites para treinar junto, com o local escolhido) só podem ser lidas por quem mandou e por quem recebeu, e só dá para mandar para quem adicionou você; ficam guardadas no servidor e o app mostra as dos últimos 90 dias. No X1 vão o seu nome, o bro escolhido e o total que você fez na métrica; numa troca, os bros que você pode trocar (nome, forma e XP) ficam visíveis para os seus amigos. Rotinas que você publica são vistas por todos, com o seu nome. Num check-in de liga vão também a prova que a liga pede (se a foto é da câmera do app ou da galeria, a hora dela, se tem local e o aparelho que gravou o treino, o nome da academia quando a localização registrou a sua visita nela durante o treino) e, em ligas com revisão, a decisão do dono. Quem organiza uma liga pode exportar os check-ins dela numa planilha. As preferências de notificação, os amigos de quem você escondeu os seus treinos ou silenciou, e os check-ins que você já viu no Deck dos Bros também ficam na conta."),
        ("Denúncias, bloqueios e filtro", "Quando você denuncia um check-in, foto, comentário, recado, mensagem ou perfil, o app envia ao servidor o tipo e o identificador do conteúdo, quem o publicou e o motivo escolhido. Só a moderação do GymBros lê as denúncias, para analisar em até 24 horas, remover o conteúdo e expulsar quem viola os termos de uso; o que você denunciou some na hora para você. Ao bloquear alguém, o servidor guarda o identificador, o nome e a data do bloqueio, para esconder de você o que essa pessoa publica e impedir que ela te mande mensagens, te desafie ou te proponha trocas. O filtro de palavras confere o texto no próprio iPhone, antes de enviar, e não guarda nem envia o que foi barrado."),
        ("Quem trata os seus dados", "O GymBros usa o Firebase (Google LLC) para login e banco de dados, com os dados no Brasil (região de São Paulo) e criptografados em repouso pelo Google. O Google trata esses dados só para prestar o serviço ao GymBros, que não usa o Google Analytics nem anúncios. Vídeos de exercícios são carregados do site wger.de quando você abre um deles; como em qualquer acesso a um site, o servidor recebe o endereço IP do aparelho. Traduções de instruções acontecem no próprio iPhone."),
        ("Sair, backup e exclusão", "\"Sair da conta\" salva os seus dados na conta e depois os tira do iPhone. O backup é uma cópia extra num arquivo que você exporta e guarda onde quiser; o app não envia esse arquivo a ninguém. \"Excluir conta\", em Ajustes > Conta, apaga do servidor o seu login, o perfil, a cópia da conta, check-ins, recados, lugar nas ligas, amizades, bloqueios, denúncias, rotinas publicadas, o treino ao vivo e os bros para troca, e apaga tudo do iPhone. Mensagens, X1 e trocas também pertencem à outra pessoa e continuam com ela, sem o seu perfil. Para pedir a exclusão delas, use o contato abaixo."),
        ("Crianças", "O app não é direcionado a menores de 13 anos e não coleta dados de crianças de propósito."),
        ("Contato", "Dúvidas sobre privacidade ou pedidos sobre os seus dados (acesso, correção, exclusão): abra uma issue em github.com/Alonsojrr14/gymbros."),
    ]
}

struct PrivacyPolicyView: View {
    var body: some View {
        GMModal("Privacidade") {
            ForEach(PrivacyPolicy.sections, id: \.title) { section in
                GMSection(section.title) {
                    Text(section.text)
                        .font(.footnote)
                        .foregroundStyle(Theme.dim)
                }
            }
            GMSection(footer: "Atualizada em \(PrivacyPolicy.updated).") {
                Link(destination: PrivacyPolicy.url) {
                    Label("Ver na web", systemImage: "link").font(.subheadline.weight(.semibold))
                }
            }
        }
    }
}
